export function routeAgent(task: string): AgentEntry[] {
  const taskLower = task.toLowerCase();
  const scores = FULL_AGENT_REGISTRY.map((agent) => {
    let score = 0;
    const text = `${agent.name} ${agent.role} ${agent.capabilities.join(' ')}`.toLowerCase();
    taskLower.split(/\s+/).forEach((word) => { if (text.includes(word)) score += 1; });
    if (agent.status === 'active') score += 0.5;
    return { agent, score };
  });
  return scores.filter((s) => s.score > 0).sort((a, b) => b.score - a.score).slice(0, 5).map((s) => s.agent);
}
